import*as THREE from'three';import{Button}from'../../core/index.js';import{FACE}from'../../modeling/parts.js';import{spec}from'./dimensions.js';
/** Deforms only the actual integral U-cut side tongue, retaining its hinge. */
export class NativeButton extends Button{
 constructor(shell){const hit=new THREE.Mesh(new THREE.PlaneGeometry(5.6,9.8),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));hit.name='PoE-P4 native side tongue input target';super({id:'user',label:'G45 UserKey · physical input intent',mesh:hit,position:spec.user.position,quaternion:FACE.left,travel:spec.user.travelMm,longPressMs:3000,meta:{role:'visual-control',visualMotion:'native-flexure',surfaceFace:'left',scope:'External press/release/cancel intent and native tongue motion only;no3sboot,reset,network,USB,power,RGB or automatic firmware action.',travelSource:'Appearance estimate;not a rated mechanical stop or material simulation.'}});this.shell=shell;this.restPositions=shell.geometry.attributes.position.array.slice();this.restNormals=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.restPositions.length/3);this.slopes=new Float32Array(this.weights.length);this.lastDepth=0;
  for(let i=0;i<this.weights.length;i++){const[x,y,z]=this.restPositions.slice(i*3,i*3+3);if(x> -10.15||y< -12.381||y> -6.619||z<spec.user.hingeZ-.001||z>spec.user.freeZ+.001)continue;const t=THREE.MathUtils.clamp((z-spec.user.hingeZ)/(spec.user.freeZ-spec.user.hingeZ),0,1);this.weights[i]=t*t*(3-2*t);this.slopes[i]=6*t*(1-t)/(spec.user.freeZ-spec.user.hingeZ);}
  this.meta.deformedNativeVertices=this.weights.filter(v=>v>0).length;
 }
 update(dt){const changed=super.update(dt),depth=this.getActuationState().depthMm;if(depth===this.lastDepth)return changed;const p=this.shell.geometry.attributes.position,n=this.shell.geometry.attributes.normal;for(let i=0;i<this.weights.length;i++){if(!this.weights[i])continue;const o=i*3,x=this.restPositions[o],y=this.restPositions[o+1],z=this.restPositions[o+2];p.setXYZ(i,x+depth*this.weights[i],y,z);let nx=this.restNormals[o],ny=this.restNormals[o+1],nz=this.restNormals[o+2];if(depth){nz-=depth*this.slopes[i]*nx;const length=Math.hypot(nx,ny,nz);nx/=length;ny/=length;nz/=length;}n.setXYZ(i,nx,ny,nz);}p.needsUpdate=true;n.needsUpdate=true;this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();if(this.follower)this.follower.position.x=this.followerRest+depth*.5;this.lastDepth=depth;return true;}
 dispose(){super.dispose();this.shell=null;this.restPositions=null;this.restNormals=null;this.weights=null;this.slopes=null;this.follower=null;}
}
